def guide(lesson, title, body):
    return {"lesson": lesson, "key": "start_packet_20261003", "type": "rich_text", "title": title,
            "content": {"body": body, "sources": [{"label": "Начален маршрут и учебна папка", "url": START_URL}]}}


def checkpoint(lesson, key, title, skill, task):
    task["content"]["skillName"] = skill
    return {"lesson": lesson, "key": key, "type": task["type"], "title": title, **{k: v for k, v in task.items() if k != "type"}}


